import pandas as pd,numpy as np
from scipy.optimize import least_squares
files=['train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_amb_op1.csv','train/A_load_op2.csv']
D=[pd.read_csv(f) for f in files]
def sim(p,d,dt=0.002):
    Kd,Tp,Tw,Kv,Tq,kq=p
    t=d.time_s.values; V=d.voltage_pu.values; th=d.bus_angle_rad.values; Vs=d.voltage_setpoint_pu.values
    P0=d.active_power_pu.values[0]; Q0=d.reactive_power_pu.values[0]; V0=V[0]; Vs0=Vs[0]
    tt=np.arange(0,t[-1],dt); Vi=np.interp(tt,t,V); ti=np.interp(tt,t,th); Vsi=np.interp(tt,t,Vs)
    thf=ti[0]; P=P0; Q=Q0; out=[]
    for k in range(len(tt)):
        om=(ti[k]-thf)/Tw; Pt=P0-Kd*om
        Vin=Vsi[k]-kq*(Q-Q0); Qt=Q0+Kv*((Vin-Vi[k])-(Vs0-V0))
        out.append((P,Q)); thf+=dt*(ti[k]-thf)/Tw; P+=dt*(Pt-P)/Tp; Q+=dt*(Qt-Q)/Tq
    out=np.array(out); return np.interp(t,tt,out[:,0]),np.interp(t,tt,out[:,1])
def res(lp):
    p=np.exp(lp); r=[]
    for d in D:
        Pm,Qm=sim(p,d); r.append(Pm-d.active_power_pu.values); r.append(Qm-d.reactive_power_pu.values)
    return np.concatenate(r)
