import pandas as pd,numpy as np
files=['train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_amb_op1.csv','train/A_load_op2.csv']
def arx(nq,nv,step=1):
    X=[];Y=[]
    for f in files:
        d=pd.read_csv(f)
        Q=d.reactive_power_pu.values; V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values; P=d.active_power_pu.values
        n=max(nq,nv)
        for k in range(n,len(Q)-1):
            row=[Q[k-i] for i in range(nq)]+[V[k-i] for i in range(nv)]+[Vs[k-i] for i in range(nv)]+[P[k]]+[1.0]
            X.append(row); Y.append(Q[k+1])
    X=np.array(X);Y=np.array(Y)
    c=np.linalg.lstsq(X,Y,rcond=None)[0]
    return c, np.sqrt(np.mean((X@c-Y)**2))
for nq,nv in [(1,1),(2,2),(3,3),(4,4)]:
    c,r=arx(nq,nv); print(nq,nv,r); print(c.round(4))

